package com.asmj.marketplace.controller;
import com.asmj.marketplace.engagement.*; import com.asmj.marketplace.model.*; import com.asmj.marketplace.order.*; import com.asmj.marketplace.product.*; import com.asmj.marketplace.repository.UserAccountRepository;
import jakarta.servlet.http.HttpSession; import java.security.Principal; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class CustomerEngagementController {
 private final WishlistRepository wishlist; private final RecentlyViewedRepository recent; private final StockAlertRepository alerts; private final ProductRepository products; private final UserAccountRepository users; private final MarketplaceOrderRepository orders;
 public CustomerEngagementController(WishlistRepository w,RecentlyViewedRepository r,StockAlertRepository a,ProductRepository p,UserAccountRepository u,MarketplaceOrderRepository o){wishlist=w;recent=r;alerts=a;products=p;users=u;orders=o;}
 @GetMapping("/customer/wishlist") public String wishlist(Principal p,Model m){UserAccount u=customer(p);List<Product> list=wishlist.findByCustomerUserIdOrderByCreatedAtDesc(u.getId()).stream().map(x->products.findById(x.getProductId()).orElse(null)).filter(x->x!=null&&x.getStatus()==ProductStatus.ACTIVE).toList();m.addAttribute("products",list);return "customer/wishlist";}
 @PostMapping("/customer/wishlist/{id}/add") public String add(@PathVariable String id,Principal p,RedirectAttributes ra){UserAccount u=customer(p);Product product=products.findById(id).filter(x->x.getStatus()==ProductStatus.ACTIVE).orElse(null);if(product==null){ra.addFlashAttribute("errorMessage","Product is not available.");return "redirect:/products";}if(wishlist.findByCustomerUserIdAndProductId(u.getId(),id).isEmpty()){WishlistItem w=new WishlistItem();w.setCustomerUserId(u.getId());w.setProductId(id);wishlist.save(w);}ra.addFlashAttribute("successMessage","Product saved to your wishlist.");return "redirect:/products/"+id;}
 @PostMapping("/customer/wishlist/{id}/remove") public String remove(@PathVariable String id,Principal p){wishlist.deleteByCustomerUserIdAndProductId(customer(p).getId(),id);return "redirect:/customer/wishlist";}
 @GetMapping("/customer/recently-viewed") public String recentlyViewed(Principal p,Model m){UserAccount u=customer(p);List<Product> list=recent.findTop30ByCustomerUserIdOrderByViewedAtDesc(u.getId()).stream().map(x->products.findById(x.getProductId()).orElse(null)).filter(x->x!=null&&x.getStatus()==ProductStatus.ACTIVE).toList();m.addAttribute("products",list);return "customer/recently-viewed";}
 @GetMapping("/customer/alerts") public String alerts(Principal p,Model m){m.addAttribute("alerts",alerts.findByCustomerUserIdOrderByCreatedAtDesc(customer(p).getId()));return "customer/alerts";}
 @PostMapping("/customer/products/{id}/stock-alert") public String subscribe(@PathVariable String id,Principal p,RedirectAttributes ra){UserAccount u=customer(p);Product product=products.findById(id).filter(x->x.getStatus()==ProductStatus.ACTIVE).orElse(null);if(product==null)return "redirect:/products";if(product.getStockQuantity()!=null&&product.getStockQuantity()>0){ra.addFlashAttribute("successMessage","This product is currently in stock.");return "redirect:/products/"+id;}StockAlertSubscription a=alerts.findByCustomerUserIdAndProductId(u.getId(),id).orElseGet(StockAlertSubscription::new);a.setCustomerUserId(u.getId());a.setProductId(id);a.setProductName(product.getName());a.setCustomerEmail(u.getEmail());a.setNotified(false);a.setNotifiedAt(null);a.setCreatedAt(Instant.now());alerts.save(a);ra.addFlashAttribute("successMessage","Availability alert subscription saved. Check My alerts for updates.");return "redirect:/products/"+id;}
 @PostMapping("/customer/orders/{id}/reorder") public String reorder(@PathVariable String id,Principal p,HttpSession session,RedirectAttributes ra){UserAccount u=customer(p);MarketplaceOrder order=orders.findById(id).orElse(null);if(order==null||!u.getId().equals(order.getCustomerUserId()))return "auth/access-denied";if(order.getStatus()!=OrderStatus.COMPLETED||order.getPaymentStatus()!=PaymentStatus.VERIFIED){ra.addFlashAttribute("errorMessage","You can reorder only from a completed, payment-verified order.");return "redirect:/customer/orders";}Map<String,Integer> cart=cart(session);if(!cart.isEmpty()){ra.addFlashAttribute("errorMessage","Your cart already contains items. Complete or clear it before starting a reorder.");return "redirect:/cart";}for(OrderItem item:order.getItems()){Product product=products.findById(item.getProductId()).filter(x->x.getStatus()==ProductStatus.ACTIVE).orElse(null);if(product==null||product.getStockQuantity()==null||product.getStockQuantity()<item.getQuantity()){ra.addFlashAttribute("errorMessage","One or more products are unavailable or have insufficient stock. Review your cart.");continue;}if(!cart.isEmpty()){String vendor=cart.keySet().stream().map(products::findById).flatMap(Optional::stream).map(Product::getVendorUserId).findFirst().orElse("");if(!vendor.equals(product.getVendorUserId())){ra.addFlashAttribute("errorMessage","Your previous order contains products from multiple vendors; only the first vendor's available products were added.");continue;}}cart.put(product.getId(),item.getQuantity());}return "redirect:/cart";}
 public void recordView(String productId,Principal principal){if(principal==null)return;UserAccount u=users.findByEmailIgnoreCase(principal.getName()).orElse(null);if(u==null||u.getRole()!=Role.ROLE_CUSTOMER)return;RecentlyViewed v=recent.findByCustomerUserIdAndProductId(u.getId(),productId).orElseGet(RecentlyViewed::new);v.setCustomerUserId(u.getId());v.setProductId(productId);v.setViewedAt(Instant.now());recent.save(v);}
 private UserAccount customer(Principal p){UserAccount u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();if(u.getRole()!=Role.ROLE_CUSTOMER)throw new IllegalArgumentException("Customer account required.");return u;}
 @SuppressWarnings("unchecked") private Map<String,Integer> cart(HttpSession s){Map<String,Integer> c=(Map<String,Integer>)s.getAttribute("asmjCart");if(c==null){c=new LinkedHashMap<>();s.setAttribute("asmjCart",c);}return c;}
}
